import 'package:flutter/material.dart';
void main()=>runApp(const BuildFlowApp());
class BuildFlowApp extends StatelessWidget{const BuildFlowApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(title:'FOVAME BuildFlow',theme:ThemeData(useMaterial3:true),home:const MobileHome());}
class MobileHome extends StatelessWidget{const MobileHome({super.key});static const items=[['BF-MOB-001','Mobile Home','Operational shortcuts and action queue'],['BF-MOB-002','Delivery Scanner','Scan shipment QR; server still authorizes target'],['BF-MOB-003','Shipment Summary','Confirm shipment identity'],['BF-MOB-004','Delivery Inspection','Record quantities and evidence; final success requires server'],['BF-MOB-005','Inventory List','Site stock with last-sync indication'],['BF-MOB-006','Record Inventory Issue','Create inventory issue command'],['BF-MOB-007','Mobile Alerts','Action-oriented alerts'],['BF-MOB-008','Mobile Profile & Sync','Site scope, sync and sign out']];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('FOVAME BuildFlow')),body:ListView(children:items.map((x)=>ListTile(title:Text(x[1]),subtitle:Text('${x[0]} · ${x[2]}'),trailing:const Icon(Icons.chevron_right))).toList()));}
